import sys
import math

MOD = 998244353
G = 3

def power(base, exp):
    result = 1
    base %= MOD
    while exp > 0:
        if exp & 1:
            result = (result * base) % MOD
        base = (base * base) % MOD
        exp >>= 1
    return result

def bit_reverse(array, length):
    j = 0
    for i in range(1, length):
        bit = length >> 1
        while j >= bit:
            j -= bit
            bit >>= 1
        j += bit
        if i < j:
            array[i], array[j] = array[j], array[i]

def transform(array, length, direction):
    bit_reverse(array, length)
    size = 2
    while size <= length:
        root = power(G, (MOD - 1) // size)
        if direction == -1:
            root = power(root, MOD - 2)
        for start in range(0, length, size):
            w = 1
            for k in range(start, start + size // 2):
                u = array[k]
                v = array[k + size // 2] * w % MOD
                array[k] = (u + v) % MOD
                array[k + size // 2] = (u - v + MOD) % MOD
                w = w * root % MOD
        size <<= 1
    if direction == -1:
        inv_len = power(length, MOD - 2)
        for i in range(length):
            array[i] = array[i] * inv_len % MOD

def main():
    input_data = sys.stdin.read().strip().split()
    n, m = int(input_data[0]), int(input_data[1])
    xs = list(map(int, input_data[2:]))

    size = 1
    halfN = n // 2
    while size < (9 * halfN + 1):
        size <<= 1

    polyA = [0] * size
    polyB = [0] * size

    polyA[0] = 1
    for x in xs:
        polyB[x] = 1

    transform(polyA, size, 1)
    transform(polyB, size, 1)

    for i in range(size):
        if polyA[i] != 0 and polyB[i] != 0:
            polyA[i] = polyA[i] * power(polyB[i], halfN) % MOD
        else:
            polyA[i] = 0

    transform(polyA, size, -1)

    total = 0
    for i in range(size):
        total = (total + polyA[i] * polyA[i]) % MOD

    print(total)

if __name__ == "__main__":
    main()

